d, CAST('["数量关系", "浓度问题", "浓度计算"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_conc_b_calc", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
